// backend/server/middleware/auth.ts
var requireAdmin = async (c, next) => {
  const auth = getAuth(c);
  if (!auth?.userId) {
    return c.json({ error: "Unauthorized" }, 401);
  }
  const prisma2 = getPrisma();
  const user = await prisma2.user.findUnique({
    where: { id: auth.userId },
    select: { role: true }
  });
  if (user?.role === "ADMIN") {
    return await next();
  }
  try {
    const clerkClient = createClerkClient2({
      secretKey: process.env.CLERK_SECRET_KEY
    });
    const clerkUser = await clerkClient.users.getUser(auth.userId);
    if (clerkUser.publicMetadata?.role === "ADMIN") {
      await prisma2.user.update({
        where: { id: auth.userId },
        data: { role: "ADMIN" }
      });
      return await next();
    }
  } catch (error) {
    console.warn(`Failed to fetch Clerk user ${auth.userId} in requireAdmin middleware:`, error);
  }
  return c.json({ error: "Forbidden: Admin access required" }, 403);
};

