var ManageJobPostings = class {
  constructor(prisma2) {
    this.prisma = prisma2;
  }
  async getJobPostings() {
    return this.prisma.jobPosting.findMany({
      include: {
        _count: {
          select: { applications: true }
        }
      },
      orderBy: { createdAt: "desc" }
    });
  }
  async createJobPosting(userId, body) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user || user.role !== "ADMIN") {
      throw new ForbiddenError("Forbidden: Admin role required");
    }
    return this.prisma.jobPosting.create({
      data: body
    });
  }
  async updateJobPosting(id, data) {
    return this.prisma.jobPosting.update({
      where: { id },
      data: {
        ...data.title !== void 0 && { title: data.title },
        ...data.description !== void 0 && { description: data.description },
        ...data.payRate !== void 0 && { payRate: data.payRate },
        ...data.sector !== void 0 && { sector: data.sector },
        ...data.townId !== void 0 && { townId: data.townId },
        ...data.status !== void 0 && { status: data.status }
      },
      include: {
        _count: {
          select: { applications: true }
        }
      }
    });
  }
  async getJobPostingById(id) {
    return this.prisma.jobPosting.findUnique({
      where: { id },
      include: {
        _count: {
          select: { applications: true }
        }
      }
    });
  }
  async updateJobPostingStatus(id, status) {
    return this.prisma.jobPosting.update({
      where: { id },
      data: { status },
      include: {
        _count: {
          select: { applications: true }
        }
      }
    });
  }
  async deleteJobPosting(id) {
    return this.prisma.jobPosting.delete({
      where: { id }
    });
  }
};

// frontend/src/services/ManageUsers.ts
var ManageUsers = class {
  constructor(prisma2) {
    this.prisma = prisma2;
  }
  async getUsers() {
    const [users, applications] = await Promise.all([
      this.prisma.user.findMany({
        include: {
          application: {
            include: { jobPosting: true }
          }
        },
        orderBy: { createdAt: "desc" }
      }),
      this.prisma.application.findMany({
        include: {
          user: true,
          jobPosting: true
        },
        orderBy: { createdAt: "desc" }
      })
    ]);
    const userMap = /* @__PURE__ */ new Map();
    const emailToUserMap = /* @__PURE__ */ new Map();
    for (const u of users) {
      userMap.set(u.id, { ...u, source: "REGISTERED_USER" });
      if (u.email) {
        emailToUserMap.set(u.email.toLowerCase().trim(), u.id);
      }
    }
    for (const app13 of applications) {
      const normalizedEmail = (app13.email || "").toLowerCase().trim();
      if (app13.user && userMap.has(app13.user.id)) {
        const u = userMap.get(app13.user.id);
        if (!u.application) {
          u.application = app13;
          u.applicationId = app13.id;
        }
        continue;
      }
      if (normalizedEmail && emailToUserMap.has(normalizedEmail)) {
        const userId = emailToUserMap.get(normalizedEmail);
        const u = userMap.get(userId);
        if (u && !u.application) {
          u.application = app13;
          u.applicationId = app13.id;
        }
        continue;
      }
      const syntheticId = `app_${app13.id}`;
      userMap.set(syntheticId, {
        id: syntheticId,
        email: app13.email || `applicant-${app13.rosterRef.toLowerCase()}@catchingjobs.co.uk`,
        role: "WORKER",
        createdAt: app13.createdAt,
        updatedAt: app13.updatedAt,
        applicationId: app13.id,
        application: app13,
        source: "APPLICANT"
      });
    }
    return Array.from(userMap.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }
  async updateUserRole(userId, role) {
    const finalRole = role === "ADMIN" ? "ADMIN" : "WORKER";
    if (userId.startsWith("app_")) {
      return { id: userId, role: finalRole };
    }
    if (process.env.CLERK_SECRET_KEY) {
      try {
        const clerkClient = createClerkClient2({
          secretKey: process.env.CLERK_SECRET_KEY
        });
        await clerkClient.users.updateUserMetadata(userId, {
          publicMetadata: { role: finalRole }
        });
      } catch (err) {
        console.warn(
          "Could not update Clerk metadata directly (user might not be in Clerk yet):",
          err
        );
      }
    }
    return this.prisma.user.update({
      where: { id: userId },
      data: { role: finalRole },
      include: { application: true }
    });
  }
  async deleteUser(userId) {
    if (userId.startsWith("app_")) {
      const appId = parseInt(userId.replace("app_", ""), 10);
      return this.prisma.application.delete({
        where: { id: appId }
      });
    }
    if (process.env.CLERK_SECRET_KEY) {
      try {
        const clerkClient = createClerkClient2({
          secretKey: process.env.CLERK_SECRET_KEY
        });
        await clerkClient.users.deleteUser(userId);
      } catch (err) {
        console.warn("Could not delete user in Clerk:", err);
      }
    }
    return this.prisma.user.delete({
      where: { id: userId }
    });
  }
  async inviteUser(email, role) {
    const finalRole = role || "WORKER";
    const clerkClient = createClerkClient2({
      secretKey: process.env.CLERK_SECRET_KEY
    });
    let clerkUser;
    const userList = await clerkClient.users.getUserList({ emailAddress: [email] });
    if (userList.data && userList.data.length > 0) {
      clerkUser = userList.data[0];
    } else {
      clerkUser = await clerkClient.users.createUser({
        emailAddress: [email],
        skipPasswordRequirement: true
      });
    }
    await clerkClient.users.updateUserMetadata(clerkUser.id, {
      publicMetadata: { role: finalRole }
    });
    return this.prisma.user.upsert({
      where: { id: clerkUser.id },
      update: {
        role: finalRole
      },
      create: {
        id: clerkUser.id,
        email,
        role: finalRole,
        passwordHash: "TODO_INVITE_MOCK_HASH"
      }
    });
  }
};

